import React, { useState, useEffect } from 'react';
import { db } from '../data/db';
import { useLiveQuery } from "dexie-react-hooks";

export const FormularioPreventa = () => {
  const [formData, setFormData] = useState({ cliente: '', producto: '', cantidad: 1 });
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [sincronizando, setSincronizando] = useState(false);
  
  // Esto permite ver los pedidos guardados en la pantalla del cel
  const pedidos = useLiveQuery(() => db.pedidos.toArray());

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  const guardarLocal = async (e) => {
    e.preventDefault();
    // Se guarda en IndexedDB para persistencia offline
    await db.pedidos.add({ 
      ...formData, 
      fecha: new Date().toISOString(),
      sincronizado: 0 
    });
    setFormData({ cliente: '', producto: '', cantidad: 1 });
    alert("✔ Guardado en el cel");
  };

  // FUNCIÓN PARA MANDAR DATOS A LA LAPTOP
  const enviarALaLap = async () => {
    if (!isOnline) {
      alert("Necesitas internet para sincronizar con la laptop");
      return;
    }

    setSincronizando(true);
    const pedidosLocales = await db.pedidos.where('sincronizado').equals(0).toArray();

    if (pedidosLocales.length === 0) {
      alert("No hay pedidos nuevos para enviar");
      setSincronizando(false);
      return;
    }

    for (const pedido of pedidosLocales) {
      try {
        // Sustituye con tu IP exacta si cambia
        const respuesta = await fetch('http://192.168.1.221:3001/api/pedidos', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(pedido)
        });

        if (respuesta.ok) {
          // Si la lap confirma, marcamos como sincronizado
          await db.pedidos.update(pedido.id, { sincronizado: 1 });
        }
      } catch (error) {
        console.error("Error al conectar con la laptop:", error);
      }
    }

    setSincronizando(false);
    alert("Sincronización terminada");
  };

  return (
    <div style={{ padding: '20px' }}>
      <div style={{ background: isOnline ? '#d4edda' : '#f8d7da', padding: '10px', textAlign: 'center' }}>
        {isOnline ? '🟢 Conectado' : '🔴 Modo Offline'}
      </div>
      
      <form onSubmit={guardarLocal} style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '20px' }}>
        <input style={{ padding: '15px' }} type="text" placeholder="Cliente" value={formData.cliente} onChange={e => setFormData({...formData, cliente: e.target.value})} required />
        <input style={{ padding: '15px' }} type="text" placeholder="Producto" value={formData.producto} onChange={e => setFormData({...formData, producto: e.target.value})} required />
        <button type="submit" style={{ padding: '15px', background: '#28a745', color: '#fff', fontWeight: 'bold', border: 'none', borderRadius: '5px' }}>
          GUARDAR EN CELULAR
        </button>
      </form>

      {/* BOTÓN DE SINCRONIZACIÓN */}
      <button 
        onClick={enviarALaLap}
        disabled={sincronizando}
        style={{ 
          marginTop: '15px', 
          width: '100%', 
          padding: '15px', 
          background: '#007bff', 
          color: 'white', 
          fontWeight: 'bold', 
          border: 'none', 
          borderRadius: '5px',
          opacity: sincronizando ? 0.6 : 1
        }}
      >
        {sincronizando ? 'ENVIANDO...' : 'SINCRONIZAR CON LAPTOP'}
      </button>

      <div style={{ marginTop: '20px' }}>
        <h3>Historial Local:</h3>
        {pedidos?.map(p => (
          <div key={p.id} style={{ 
            borderBottom: '1px solid #ccc', 
            padding: '10px', 
            display: 'flex', 
            justifyContent: 'space-between',
            backgroundColor: p.sincronizado ? '#f0f0f0' : 'white'
          }}>
            <span>{p.cliente} - {p.producto}</span>
            <small>{p.sincronizado ? '✅ Sincro' : '⏳ Pendiente'}</small>
          </div>
        ))}
      </div>
    </div>
  );
};
